package com.morn24.dashboard.domain

import java.time.LocalDate
import java.time.temporal.ChronoUnit

data class TodoSummary(
    val visibleCount: Int,
    val doneCount: Int,
    val progress: Float,
)

/**
 * Kotlin port of web/rules.js. The cross-language vectors in
 * android/app/src/test/resources/rule-vectors.json (generated by scripts/gen_rule_vectors.js)
 * must keep both implementations answering identically. Dates are device-local `YYYY-MM-DD`
 * strings; `0` is Sunday in `days`.
 */
object TodoRules {
    const val HISTORY_DAYS = 90
    private val WEEK = listOf("일", "월", "화", "수", "목", "금", "토")

    fun isRepeating(todo: Todo): Boolean = todo.repeat == "daily" || todo.repeat == "weekly"

    /** 0 = Sunday ... 6 = Saturday, like JavaScript's Date.getDay(). */
    fun dow(day: String): Int = LocalDate.parse(day).dayOfWeek.value % 7

    fun addDays(day: String, n: Int): String = LocalDate.parse(day).plusDays(n.toLong()).toString()

    /** Does this repeating item have to be done on that day? */
    fun scheduledOn(todo: Todo, day: String): Boolean = when (todo.repeat) {
        "daily" -> true
        "weekly" -> dow(day) in todo.days
        else -> false
    }

    fun isDone(todo: Todo, today: String): Boolean =
        if (isRepeating(todo)) todo.doneOn == today else todo.doneOn != null

    fun isVisible(todo: Todo, today: String): Boolean {
        if (isRepeating(todo)) return scheduledOn(todo, today) || todo.doneOn == today
        val doneOn = todo.doneOn
        if (doneOn != null) return doneOn >= today
        val date = todo.date
        return date.isNullOrEmpty() || date <= today
    }

    /** One-time items finished before today ("clean up" candidates in the web app). */
    fun isStale(todo: Todo, today: String): Boolean =
        !isRepeating(todo) && todo.doneOn != null && todo.doneOn < today

    /** One-time items with a date that has not arrived yet. */
    fun isUpcoming(todo: Todo, today: String): Boolean {
        val date = todo.date
        return !isRepeating(todo) && todo.doneOn == null && !date.isNullOrEmpty() && date > today
    }

    /** Days overdue for an unfinished one-time item, or null. */
    fun lateDays(todo: Todo, today: String): Int? {
        val date = todo.date
        if (isRepeating(todo) || isDone(todo, today) || date.isNullOrEmpty() || date >= today) return null
        return runCatching {
            ChronoUnit.DAYS.between(LocalDate.parse(date), LocalDate.parse(today)).toInt()
        }.getOrNull()
    }

    /** Consecutive scheduled days done, counted back from today (or yesterday if not yet done). */
    fun streak(todo: Todo, today: String): Int {
        if (!isRepeating(todo)) return 0
        val done = LinkedHashSet<String>(todo.history.orEmpty())
        todo.doneOn?.let(done::add)
        var day = if (today in done) today else addDays(today, -1)
        var n = 0
        for (i in 0 until HISTORY_DAYS) {
            if (scheduledOn(todo, day)) {
                if (day !in done) break
                n++
            }
            day = addDays(day, -1)
        }
        return n
    }

    /** New `history` after marking [day] done or not done (keeps the last 90 days, sorted). */
    fun recordHistory(todo: Todo, day: String, done: Boolean): List<String> {
        val cutoff = addDays(day, -HISTORY_DAYS)
        val set = LinkedHashSet<String>(todo.history.orEmpty().filter { it >= cutoff })
        val doneOn = todo.doneOn
        // The last completion before `history` existed.
        if (todo.history == null && doneOn != null && doneOn != day) set.add(doneOn)
        if (done) set.add(day) else set.remove(day)
        return set.sorted()
    }

    /**
     * Same result as web/app.js toggleTodo: repeating items update `history` and restore the
     * previous completion day when cancelled; one-time items just set or clear `doneOn`.
     */
    fun applyCompletion(todo: Todo, day: String, makeDone: Boolean): Todo {
        if (!isRepeating(todo)) return todo.copy(doneOn = if (makeDone) day else null)
        val history = recordHistory(todo, day, makeDone)
        val doneOn = if (makeDone) day else history.lastOrNull { it < day }
        return todo.copy(doneOn = doneOn, history = history)
    }

    /** "매일" / "평일" / "주말" / "월·수·금" or "" (not a weekly item). */
    fun repeatLabel(todo: Todo): String {
        if (todo.repeat == "daily") return "매일"
        if (todo.repeat != "weekly") return ""
        val sorted = todo.days.sorted().joinToString(",")
        if (sorted == "1,2,3,4,5") return "평일"
        if (sorted == "0,6") return "주말"
        return todo.days.sortedBy { (it + 6) % 7 }.joinToString("·") { WEEK.getOrElse(it) { "?" } }
    }

    fun fmtDay(day: String, today: String): String {
        if (day == today) return "오늘"
        if (day == addDays(today, 1)) return "내일"
        val parsed = runCatching { LocalDate.parse(day) }.getOrNull() ?: return day
        return "${parsed.monthValue}/${parsed.dayOfMonth}(${WEEK[dow(day)]})"
    }

    /** Incomplete items first, preserving source array order within both groups. */
    fun displayOrder(todos: List<Todo>, today: String): List<Todo> {
        val visible = todos.filter { isVisible(it, today) }
        return visible.filterNot { isDone(it, today) } + visible.filter { isDone(it, today) }
    }

    fun upcoming(todos: List<Todo>, today: String): List<Todo> =
        todos.filter { isUpcoming(it, today) }.sortedBy { it.date.orEmpty() }

    fun summary(todos: List<Todo>, today: String): TodoSummary {
        val visible = todos.filter { isVisible(it, today) }
        val done = visible.count { isDone(it, today) }
        return TodoSummary(
            visibleCount = visible.size,
            doneCount = done,
            progress = if (visible.isEmpty()) 0f else done.toFloat() / visible.size,
        )
    }
}
